// Installation commands shown on /install. Every command here mirrors the
// real repos on github.com/infrahubcenter: infrahub-deploy (deploy/docker,
// deploy/kubernetes), the agent install commands generated by
// infrahub-api/internal/services/*_agent_install.go, and
// infrahub-vm-agent/install.sh. Images live on
// docker.io/infrahubcenter.

export const GO_VERSION = "1.26.0";
export const VERSION = "1.0.0";
export const GITHUB = "https://github.com/infrahubcenter";
export const REPO_URL = `${GITHUB}/infrahub-deploy.git`;
const RAW = "https://raw.githubusercontent.com/infrahubcenter";
export const DEPLOY_RAW = `${RAW}/infrahub-deploy/main/deploy`;

export const IMAGES: { name: string; role: string }[] = [
  { name: "infrahubcenter/infrahub-api", role: "Go API, schedulers, migrations (runs them on start)" },
  { name: "infrahubcenter/infrahub-ui", role: "Web console" },
  { name: "infrahubcenter/infrahub-gateway", role: "nginx entry point: /api → API, / → console" },
  { name: "infrahubcenter/infrahub-docker-agent", role: "Agent for Docker hosts" },
  { name: "infrahubcenter/infrahub-vm-agent", role: "Agent for Linux VMs (metrics + journal logs)" },
  { name: "infrahubcenter/infrahub-k8s-agent", role: "In-cluster Kubernetes agent" },
];

export type Distro = {
  id: string;
  label: string;
  hint: string;
  code: string;
  note?: string;
};

