export const HOST_COMMON: { title: string; body?: string; code: string; file?: string }[] = [
  {
    title: "Install Go",
    body: "Distro Go packages are usually too old; the API needs Go 1.26+.",
    code: `curl -fsSL https://go.dev/dl/go${GO_VERSION}.linux-amd64.tar.gz | sudo tar -C /usr/local -xz
export PATH=$PATH:/usr/local/go/bin
go version`,
  },
  {
    title: "Create the service user, database and get the source",
    code: `sudo useradd --system --create-home --home-dir /opt/infrahub --shell /usr/sbin/nologin infrahub
sudo git clone ${GITHUB}/infrahub-api.git /opt/infrahub/src/infrahub-api
sudo git clone ${GITHUB}/infrahub-ui.git  /opt/infrahub/src/infrahub-ui

sudo -u postgres psql -c "CREATE USER infrahub WITH PASSWORD '<db-password>';"
sudo -u postgres psql -c "CREATE DATABASE infrahub OWNER infrahub;"`,
  },
  {
    title: "Build the API",
    code: `cd /opt/infrahub/src/infrahub-api
sudo mkdir -p /opt/infrahub/api
for c in server migrate seed bootstrap-admin gen-encryption-key encrypt-config-value; do
  sudo CGO_ENABLED=0 /usr/local/go/bin/go build -trimpath -ldflags="-s -w" -o /opt/infrahub/api/$c ./cmd/$c
done
sudo cp -r migrations production.ini.enc /opt/infrahub/api/`,
  },
  {
    title: "Generate secrets and configure",
    body: "Paste each ENC(...) value into /opt/infrahub/api/production.ini.enc (DATABASE_URL, JWT_SECRET, SSH_CREDENTIAL_ENCRYPTION_KEY, BOOTSTRAP_ADMIN_*), and set PUBLIC_URL to your domain.",
    code: `cd /opt/infrahub/api
export INFRAHUB_MASTER_KEY=$(./gen-encryption-key)

sudo install -d -m 0750 -o root -g infrahub /etc/infrahub
echo "INFRAHUB_MASTER_KEY=$INFRAHUB_MASTER_KEY" | sudo tee /etc/infrahub/api.env > /dev/null
sudo chmod 0640 /etc/infrahub/api.env && sudo chgrp infrahub /etc/infrahub/api.env

./encrypt-config-value 'postgres://infrahub:<db-password>@localhost:5432/infrahub?sslmode=disable'  # DATABASE_URL
./encrypt-config-value "$(openssl rand -base64 48)"                                                # JWT_SECRET
./encrypt-config-value "$(./gen-encryption-key)"                                                   # SSH_CREDENTIAL_ENCRYPTION_KEY
./encrypt-config-value '<first-admin-password>'                                                     # BOOTSTRAP_ADMIN_PASSWORD

sudo -E nano /opt/infrahub/api/production.ini.enc`,
  },
  {
    title: "Migrate, seed and create the first admin",
    code: `cd /opt/infrahub/api
sudo -u infrahub env APP_ENV=production INFRAHUB_MASTER_KEY=$INFRAHUB_MASTER_KEY ./migrate up
sudo -u infrahub env APP_ENV=production INFRAHUB_MASTER_KEY=$INFRAHUB_MASTER_KEY ./seed
sudo -u infrahub env APP_ENV=production INFRAHUB_MASTER_KEY=$INFRAHUB_MASTER_KEY ./bootstrap-admin
sudo chown -R infrahub:infrahub /opt/infrahub`,
  },
  {
    title: "Build the console",
    body: "NEXT_PUBLIC_API_BASE_URL is baked in at build time -- rebuild if your domain changes.",
    code: `cd /opt/infrahub/src/infrahub-ui
npm ci
NEXT_PUBLIC_API_BASE_URL=https://infrahub.example.com npm run build

sudo mkdir -p /opt/infrahub/ui/.next
sudo cp -r .next/standalone/. /opt/infrahub/ui/
sudo cp -r public /opt/infrahub/ui/public
sudo cp -r .next/static /opt/infrahub/ui/.next/static
sudo chown -R infrahub:infrahub /opt/infrahub/ui`,
  },
  {
    title: "systemd units",
    file: "/etc/systemd/system/infrahub-api.service  +  infrahub-ui.service",
    code: `sudo tee /etc/systemd/system/infrahub-api.service > /dev/null <<'EOF'
[Unit]
Description=Infra Hub Center API
After=network-online.target postgresql.service postgresql-16.service
Wants=network-online.target

[Service]
User=infrahub
WorkingDirectory=/opt/infrahub/api
Environment=APP_ENV=production
EnvironmentFile=/etc/infrahub/api.env
ExecStart=/opt/infrahub/api/server
Restart=always
NoNewPrivileges=true

[Install]
WantedBy=multi-user.target
EOF

sudo tee /etc/systemd/system/infrahub-ui.service > /dev/null <<'EOF'
[Unit]
Description=Infra Hub Center Console
After=network-online.target infrahub-api.service

[Service]
User=infrahub
WorkingDirectory=/opt/infrahub/ui
Environment=NODE_ENV=production PORT=3000 HOSTNAME=127.0.0.1 INFRAHUB_PLAN=community
ExecStart=/usr/bin/node /opt/infrahub/ui/server.js
Restart=always
NoNewPrivileges=true

[Install]
WantedBy=multi-user.target
EOF

sudo systemctl daemon-reload
sudo systemctl enable --now infrahub-api infrahub-ui`,
  },
  {
    title: "nginx reverse proxy",
    body: "One origin: /api/* (including WebSockets for console, live logs and agents) goes to the API, everything else to the console. Add TLS with certbot --nginx.",
    file: "/etc/nginx/conf.d/infrahub.conf",
    code: `sudo tee /etc/nginx/conf.d/infrahub.conf > /dev/null <<'EOF'
map $http_upgrade $connection_upgrade { default upgrade; '' close; }

server {
    listen 80;
    server_name infrahub.example.com;
    client_max_body_size 50m;

    location /api/ {
        proxy_pass http://127.0.0.1:8080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 1h;
    }

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
EOF

sudo nginx -t && sudo systemctl enable --now nginx && sudo systemctl reload nginx
curl -s http://localhost/api/health`,
  },
];

// --- Agents ---
export const AGENT_DOCKER_HOST = `# Console: Agents & Integrations → Docker Host Onboarding → Install Agent
# copies this exact command with your backend URL and a one-time token:
docker run -d --name infrahub-docker-agent --restart unless-stopped \\
  -v /var/run/docker.sock:/var/run/docker.sock -v /proc:/host/proc:ro -v /:/host/root:ro \\
  -e INFRAHUB_BACKEND_URL='<backend-url>' -e INFRAHUB_AGENT_TOKEN='<token>' \\
  docker.io/infrahubcenter/infrahub-docker-agent:${VERSION}`;

export const AGENT_VM_DOCKER = `# Console: Compute → Host Metrics & Logs → Configure → VM Agent
docker run -d --name infrahub-vm-agent --restart unless-stopped \\
  -v /proc:/host/proc:ro -v /:/host/root:ro \\
  -v /var/log:/host/var/log:ro -v /var/log/journal:/host/var/log/journal:ro -v /run/log/journal:/host/run/log/journal:ro \\
  -e INFRAHUB_BACKEND_URL='<backend-url>' -e INFRAHUB_AGENT_TOKEN='<token>' -e INFRAHUB_METRICS_INTERVAL=15 \\
  docker.io/infrahubcenter/infrahub-vm-agent:${VERSION}`;

export const AGENT_VM_NATIVE = `# apt (Ubuntu/Debian), dnf (RHEL/Rocky/Alma/Fedora/Amazon Linux 2023),
# yum (CentOS 7/Amazon Linux 2), zypper (SUSE/openSUSE). Installs a systemd service.
curl -fsSL ${RAW}/infrahub-vm-agent/main/install.sh \\
  | sudo bash -s -- --backend-url '<backend-url>' --token '<token>'

systemctl status infrahub-vm-agent
journalctl -u infrahub-vm-agent -f

# Remove:
curl -fsSL ${RAW}/infrahub-vm-agent/main/install.sh | sudo bash -s -- --uninstall`;

export const AGENT_K8S = `# Console: Agents & Integrations → Kubernetes Cluster Onboarding → Connect Cluster
# shows your backend URL and a one-time token. Then, in the cluster to monitor:
kubectl create namespace infrahub-agent
kubectl create secret generic infrahub-k8s-agent -n infrahub-agent \\
  --from-literal=backend-url='<backend-url>' \\
  --from-literal=agent-token='<token>'
kubectl apply -f ${RAW}/infrahub-k8s-agent/main/deploy/manifest.yaml

kubectl -n infrahub-agent get pods`;
